SELECT w.id AS wallet_trade_id, w.symbol AS exit_symbol, w.executed_at, e.id, e.symbol, e.observed_at, e.created_at, ROUND(TIMESTAMPDIFF(MICROSECOND, e.observed_at, e.created_at)/1000,1) AS created_minus_observed_ms FROM wallet_trade w JOIN market_price_event e ON e.id BETWEEN 1340000 AND 1530000 AND e.created_at BETWEEN w.executed_at - INTERVAL 2 SECOND AND w.executed_at + INTERVAL 4 SECOND WHERE w.id IN (201,219,232,247,259,265) ORDER BY w.id, e.created_at LIMIT 600